+const { useState } = React;
+
+function ConsentForm() {
+  const [agreed, setAgreed] = useState(false);
+  const [status, setStatus] = useState(null);
+
+  const handleSubmit = (e) => {
+    e.preventDefault();
+    if (!agreed) {
+      setStatus({ type: "error", message: "You must agree to the terms to continue." });
+      return;
+    }
+    setStatus({ type: "success", message: "Thanks! Your consent has been recorded." });
+  };
+
+  return (
+    <div className="card">
+      <h1>Before you continue</h1>
+      <p className="lede">
+        Please review and accept our terms of use to create your account.
+      </p>
+
+      <form onSubmit={handleSubmit} noValidate>
+        <div className="form-field">
+          <input
+            id="terms"
+            type="checkbox"
+            required
+            checked={agreed}
+            onChange={(e) => {
+              setAgreed(e.target.checked);
+              if (status) setStatus(null);
+            }}
+          />
+          <div className="field-text">
+            <label htmlFor="terms">
+              I agree to the <a href="#" onClick={(e) => e.preventDefault()}>Terms of Use</a>
+              <span className="required" aria-hidden="true">*</span>
+            </label>
+            <span className="helper">
+              Required. By checking this box, you confirm you have read and accept our terms.
+            </span>
+          </div>
+        </div>
+
+        <div className="actions">
+          <button type="submit">Continue</button>
+        </div>
+
+        {status && (
+          <div className={`status ${status.type}`} role="alert">
+            {status.message}
+          </div>
+        )}
+      </form>
+    </div>
+  );
+}
+
+const root = ReactDOM.createRoot(document.getElementById("root"));
+root.render(<ConsentForm />);
+
')
